local _, addon = ...
addon.localeData.enUS.texts = {
    POWER_WORD_FORTITUDE = { gruppe = { "Stand tall. Your courage outlasts doubt.", "Courage cannot be handed over. But it can be steadied.", "*draws a steadfast sign of Light before the chest.*", "*rests a hand on the shoulder as a golden rune flares.*" }, ziel = { "Stand tall. Your courage outlasts doubt.", "%s, may your strength hold when your legs grow tired.", "*draws a steadfast sign of Light before the chest.*", "*rests a hand on the shoulder as a golden rune flares.*" }, },
    POWER_WORD_SHIELD = { gruppe = { "Sometimes a moment of safety is the greatest miracle.", "Another blow may come. This Light shall meet it.", "*touches two fingers to the wrist and raises a golden ward.*", "*tests the shimmering barrier with a calm motion of the hand.*" }, ziel = { "Sometimes a moment of safety is the greatest miracle.", "%s, this ward buys you the moment you need.", "*touches two fingers to the wrist and raises a golden ward.*", "*tests the shimmering barrier with a calm motion of the hand.*" }, },
    CONFOUNDING_FLASH = { gruppe = { "One spark of confusion can be the wisest answer.", "One bright instant of confusion can undo an entire plan.", "*flicks a wavering point of Light that briefly distorts the view.*", "*tilts the head as though studying the effect of the sudden flash.*" }, },
    STARSHARDS = { gruppe = { "The stars have been silent long enough. Now they answer.", "What is distant in the sky can strike sharply down here.", "*traces a constellation and draws glittering shards from its shape.*", "*reaches upward as tiny lights descend in an arc.*" }, ziel = { "The stars have been silent long enough. Now they answer.", "%s, even the distant stars have noticed you.", "*traces a constellation and draws glittering shards from its shape.*", "*reaches upward as tiny lights descend in an arc.*" }, },
    INNER_FIRE = { gruppe = { "One small flame can defy a whole winter.", "The ember within me needs neither wood nor wind.", "*presses both palms to the chest until warmth glows through the robe.*", "*draws a small ring of flame close around the body.*" }, },
    DISPEL_MAGIC = { gruppe = { "Strange magic, your time has run out.", "Not every foreign enchantment deserves a place in this world.", "*catches an unseen thread and unravels it from the spellwork.*", "*sweeps away the last stray sparks with an open palm.*" }, },
    CONTINGENCY_PLAN = { gruppe = { "I trust the Light, but I prepare for the worst.", "Preparing for the worst is not doubting the Light. It is caring ahead.", "*layers two shining signs, leaving one hidden beneath the other.*", "*checks the discreet protective seal on a companion's shoulder.*" }, ziel = { "I trust the Light, but I prepare for the worst.", "%s, if all goes wrong, let this blessing catch you.", "*layers two shining signs, leaving one hidden beneath the other.*", "*checks the discreet protective seal on a companion's shoulder.*" }, },
    ELUNES_GRACE = { gruppe = { "Elune, let me pass between their blows.", "Between two heartbeats, the moon grants me one safe step.", "*traces a crescent and glides aside from the incoming blow.*", "*lowers the gaze as silver light shimmers around the body's outline.*" }, },
    FEEDBACK = { gruppe = { "Touch my thoughts and find a mirror of thorns.", "Whoever rattles my mind may awaken doubts of their own.", "*draws a shimmering veil close around the temples.*", "*lets tiny thorns of Light flash and reflect inward.*" }, },
    SHACKLE_UNDEAD = { gruppe = { "Be still, lost soul. Your journey pauses here.", "Death did not release you. For a moment, neither will my magic.", "*loops a pale ribbon of Light around an unseen figure.*", "*holds the palm perfectly still as the binding seal tightens.*" }, ziel = { "Be still, lost soul. Your journey pauses here.", "%s, remain still. The living must pass.", "*loops a pale ribbon of Light around an unseen figure.*", "*holds the palm perfectly still as the binding seal tightens.*" }, },
    MANA_BURN = { gruppe = { "Your magic crackles so loudly I almost pity it.", "You left your power exposed. I'm merely taking the excess.", "*closes the fingers as though snuffing an unseen flame.*", "*pulls a glowing spark from the enemy's spellwork.*" }, ziel = { "Your magic crackles so loudly I almost pity it.", "%s, your magic will tire before your pride does.", "*closes the fingers as though snuffing an unseen flame.*", "*pulls a glowing spark from the enemy's spellwork.*" }, },
    DIVINE_SPIRIT = { gruppe = { "Your thoughts need no cage, only a steady anchor.", "Clarity grows when we leave no room for needless noise.", "*touches the brow with two fingers and guides a bright thread toward an ally.*", "*opens both hands as though a calm thought were spreading outward.*" }, ziel = { "Your thoughts need no cage, only a steady anchor.", "%s, keep your mind clear even when the world grows loud.", "*touches the brow with two fingers and guides a bright thread toward an ally.*", "*opens both hands as though a calm thought were spreading outward.*" }, },
    PENANCE = { gruppe = { "Judgment can be both wound and bandage.", "Three moments suffice: understand, act, and hope again.", "*moves the hand in short, precise arcs through a beam of Light.*", "*pauses as the final glow fades from the palm.*" }, },
    LEVITATE = { gruppe = { "The ground can have me back later.", "It is remarkable how small worries seem when your feet leave the ground.", "*lifts the heels as fine dust floats beneath the boots.*", "*spreads both arms and rises a finger's width above the earth.*" }, },
    PRAYER_OF_FORTITUDE = { gruppe = { "May none of us lose heart today.", "Our strength grows when no one faces the next step alone.", "*spreads both arms as several golden warding signs appear.*", "*bows the head while the blessing moves from one companion to another.*" }, },
    PRAYER_OF_SPIRIT = { gruppe = { "We breathe apart, yet hope together.", "May our thoughts differ while our hope remains shared.", "*joins several glimmering points of Light with a steady gesture.*", "*listens for a heartbeat as a quiet blessing settles over the group.*" }, },
    INNER_FOCUS = { gruppe = { "Every voice falls silent. One purpose remains.", "No doubt, no distraction. Only the next breath remains.", "*closes the eyes and folds both hands in stillness.*", "*takes one deep breath until the Light around the fingertips settles.*" }, },
    POWER_INFUSION = { gruppe = { "Take this power, and make something good of it.", "I give you not only strength, but my trust.", "*channels a bright current from one hand toward an ally.*", "*opens the fingers as a taut strand of energy is released.*" }, ziel = { "Take this power, and make something good of it.", "%s, take this strength and use it wisely.", "*channels a bright current from one hand toward an ally.*", "*opens the fingers as a taut strand of energy is released.*" }, },
    LESSER_HEAL = { gruppe = { "Not every wound needs a miracle, some need patience.", "A little Light, a little rest. That is all we need for now.", "*moves a warm spark of Light across a small injury.*", "*touches two fingers to the bandage and relaxes the hand.*" }, ziel = { "Not every wound needs a miracle, some need patience.", "%s, this small wound will not stop us.", "*moves a warm spark of Light across a small injury.*", "*touches two fingers to the bandage and relaxes the hand.*" }, },
    SMITE = { gruppe = { "The Light can be gentle. Not today.", "A judgement needs no blade when the Light itself answers.", "*brings the hand sharply down as a bright seam opens overhead.*", "*fixes the gaze ahead as a beam of Light strikes.*" }, ziel = { "The Light can be gentle. Not today.", "%s, this is no sermon. This is the answer.", "*brings the hand sharply down as a bright seam opens overhead.*", "*fixes the gaze ahead as a beam of Light strikes.*" }, },
    RENEW = { gruppe = { "Healing is not a moment. It is a promise.", "With each breath, the body finds another measure of strength.", "*holds the fingertips over a wound as tiny sparks of Light rise.*", "*draws a slow circle over the bandage until the glow lingers.*" }, ziel = { "Healing is not a moment. It is a promise.", "%s, the healing will continue. Give it a little time.", "*holds the fingertips over a wound as tiny sparks of Light rise.*", "*draws a slow circle over the bandage until the glow lingers.*" }, },
    DESPERATE_PRAYER = { gruppe = { "When words fail, one last prayer remains.", "Even in the worst storm, a heart can find its rhythm.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, },
    DIVINE_GRACE = { gruppe = { "Not yet. This life has more chapters to tell.", "Even in the worst storm, a heart can find its rhythm.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, ziel = { "Not yet. This life has more chapters to tell.", "Hold on, %s. Your story is not finished here.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, },
    RESURRECTION = { gruppe = { "The story is not over. Can you hear me?", "The Light can reach even those who no longer hear our voices.", "*kneels beside the still body and gently holds both hands above it.*", "*holds the sacred symbol steady until the first warm glow appears.*" }, ziel = { "The story is not over. Can you hear me?", "%s, come back to us. Your place is still waiting.", "*kneels beside the still body and gently holds both hands above it.*", "*holds the sacred symbol steady until the first warm glow appears.*" }, },
    CURE_DISEASE = { gruppe = { "What crept inside can leave again.", "Even in the worst storm, a heart can find its rhythm.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, ziel = { "What crept inside can leave again.", "Hold on, %s. Your story is not finished here.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, },
    HEAL = { gruppe = { "Breathe. The next step is yours.", "Now more than skin must mend. Strength must return as well.", "*rests both hands near the injury and gathers the Light together.*", "*waits as a warm glow spreads evenly across the bandage.*" }, ziel = { "Breathe. The next step is yours.", "%s, take this breath. The next will come easier.", "*rests both hands near the injury and gathers the Light together.*", "*waits as a warm glow spreads evenly across the bandage.*" }, },
    CHASTISE = { gruppe = { "One word suffices, when spoken with conviction.", "Even in the worst storm, a heart can find its rhythm.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, ziel = { "One word suffices, when spoken with conviction.", "Your next thought will be more careful, %s.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, },
    FEAR_WARD = { gruppe = { "Your courage is yours. I merely guard it.", "Fear may come. It will not be your master.", "*draws a firm circle before the companion's brow.*", "*closes a hand around a mark of Light that remains as a ward.*" }, ziel = { "Your courage is yours. I merely guard it.", "%s, listen to your courage, not to fear's whispers.", "*draws a firm circle before the companion's brow.*", "*closes a hand around a mark of Light that remains as a ward.*" }, },
    FLASH_HEAL = { gruppe = { "No time for sermons. Stay with us!", "Every second counts. This prayer must be enough.", "*thrusts a hand forward as a brief flash of Light erupts.*", "*catches a breath while the healing Light is already at work.*" }, ziel = { "No time for sermons. Stay with us!", "%s, stay with me! The Light is already here.", "*thrusts a hand forward as a brief flash of Light erupts.*", "*catches a breath while the healing Light is already at work.*" }, },
    HOLY_FIRE = { gruppe = { "When light burns, no lie can hide.", "This fire comes from no forge. It answers to my faith.", "*closes a fist around a bright spark, then releases it with an open hand.*", "*watches the trail of golden fire without flinching.*" }, ziel = { "When light burns, no lie can hide.", "%s, the Light has a burning answer for you today.", "*closes a fist around a bright spark, then releases it with an open hand.*", "*watches the trail of golden fire without flinching.*" }, },
    HOLY_NOVA = { gruppe = { "Let us drive back the darkness together.", "One burst of Light, so everyone may breathe again.", "*opens both arms and sends a ring of brilliant Light outward.*", "*turns at the centre of a golden wave and slowly lowers both hands.*" }, },
    PRAYER_OF_HEALING = { gruppe = { "A breath of hope for each of you.", "For those still standing, and those who can barely stand.", "*raises both hands as threads of Light move toward the companions.*", "*bows the head as a shared prayer moves through the group like warmth.*" }, },
    ABOLISH_DISEASE = { gruppe = { "This sickness has no right to stay.", "Even in the worst storm, a heart can find its rhythm.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, ziel = { "This sickness has no right to stay.", "Hold on, %s. Your story is not finished here.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, },
    GREATER_HEAL = { gruppe = { "Hold on. Give me a moment and I'll give you many more.", "Even in the worst storm, a heart can find its rhythm.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, ziel = { "Hold on. Give me a moment and I'll give you many more.", "Hold on, %s. Your story is not finished here.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, },
    LIGHTWELL = { gruppe = { "A quiet place where courage grows roots again.", "Even in the worst storm, a heart can find its rhythm.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, },
    LIGHTWELL_RENEW = { gruppe = { "One drop of hope can still be shared.", "Even in the worst storm, a heart can find its rhythm.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, ziel = { "One drop of hope can still be shared.", "Hold on, %s. Your story is not finished here.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, },
    PRAYER_OF_MENDING = { gruppe = { "May my blessing find whoever needs it next.", "Even in the worst storm, a heart can find its rhythm.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, ziel = { "May my blessing find whoever needs it next.", "Hold on, %s. Your story is not finished here.", "*raises open hands in silent prayer*", "*lets light gather between the fingers*" }, },
    SHADOW_WORD_PAIN = { gruppe = { "One word. The rest is your memory of it.", "One syllable is enough to wrap a thought in thorns.", "*lowers the chin as a dark mark forms above the palm.*", "*releases a harsh whisper with no visible source.*" }, ziel = { "One word. The rest is your memory of it.", "%s, this word will stay with you longer than you wish.", "*lowers the chin as a dark mark forms above the palm.*", "*releases a harsh whisper with no visible source.*" }, },
    FADE = { gruppe = { "You need not vanish to go unnoticed.", "One step beyond their notice is enough. The shadows do the rest.", "*draws the cloak's shadow over the shoulders like a veil.*", "*lowers the gaze and seems to vanish into the crowd.*" }, },
    HEX_OF_WEAKNESS = { gruppe = { "Strength is a story you have been told too often.", "A curse needs no blade to take away strength.", "*weaves three dark signs into a narrow band.*", "*opens a hand and releases a trembling rune.*" }, ziel = { "Strength is a story you have been told too often.", "%s, your strength has just acquired an unexpected cost.", "*weaves three dark signs into a narrow band.*", "*opens a hand and releases a trembling rune.*" }, },
    MIND_BLAST = { gruppe = { "Some doors are best left shut. Not this one.", "Your thoughts are a fortress with a remarkably weak gate.", "*presses two fingers to the temple and snaps the hand forward.*", "*sends an unseen shock rippling through the air.*" }, ziel = { "Some doors are best left shut. Not this one.", "%s, you had better hold on to your thoughts.", "*presses two fingers to the temple and snaps the hand forward.*", "*sends an unseen shock rippling through the air.*" }, },
    TOUCH_OF_WEAKNESS = { gruppe = { "Behind every touch waits another intention.", "This hand carries no weapon. That does not make it harmless.", "*watches a dim shadow crawl across the fingers.*", "*slowly closes a fist, leaving a dark trace behind.*" }, },
    PSYCHIC_SCREAM = { gruppe = { "Fear has a voice. I lend it mine.", "When the mind flees, the body needs no further order.", "*throws both arms apart as though breaking something unseen.*", "*releases a soundless scream that makes the air tremble.*" }, },
    DARK_SACRIFICE = { gruppe = { "A price must be paid. Today I know the debtor.", "Darkness speaks volumes to those who listen.", "*follows an unseen shadow with a steady gaze*", "*whispers a syllable that fades into the room*" }, },
    DEVOURING_PLAGUE = { gruppe = { "Your pride has roots. I will pull them out.", "Some decay begins with a single careless breath.", "*gathers a sickly veil of dark vapour.*", "*lowers the hand as greenish mist creeps away.*" }, ziel = { "Your pride has roots. I will pull them out.", "%s, not even your pride can shrug off this blight.", "*gathers a sickly veil of dark vapour.*", "*lowers the hand as greenish mist creeps away.*" }, },
    MIND_FLAY = { gruppe = { "A mind is delicate fabric. Hear it tearing?", "One thought after another. I shall pull them gently apart.", "*touches two fingers to the temple and draws a violet thread through the air.*", "*narrows the eyes as a thin beam of shadow pulses.*" }, ziel = { "A mind is delicate fabric. Hear it tearing?", "%s, your thoughts are losing their grip.", "*touches two fingers to the temple and draws a violet thread through the air.*", "*narrows the eyes as a thin beam of shadow pulses.*" }, },
    MIND_SOOTHE = { gruppe = { "Sleeping doubts make the best allies.", "A quiet mind asks fewer questions. That suits us well.", "*lowers a palm slowly as though smoothing an unseen wave.*", "*breathes out silently as the surrounding unrest fades.*" }, ziel = { "Sleeping doubts make the best allies.", "%s, a little calm will do you good just now.", "*lowers a palm slowly as though smoothing an unseen wave.*", "*breathes out silently as the surrounding unrest fades.*" }, },
    SHADOWGUARD = { gruppe = { "I wear my darkness with dignity. And thorns.", "Go on, strike. Shadows seldom forget who wakes them.", "*draws dark sparks into a circle around the body.*", "*turns an open palm outward as a defensive veil begins to glow.*" }, },
    MIND_VISION = { gruppe = { "Your eyes will show me things you overlook.", "Distance cannot keep your secrets from my sight.", "*touches the eyes and peers through a distant shadow.*", "*stares blankly as awareness travels elsewhere.*" }, ziel = { "Your eyes will show me things you overlook.", "%s, I can now glimpse a corner of your world.", "*touches the eyes and peers through a distant shadow.*", "*stares blankly as awareness travels elsewhere.*" }, },
    MIND_CONTROL = { gruppe = { "For a moment, your choice shall be mine.", "One borrowed thought, and the path changes.", "*slowly draws an unseen string between thumb and forefinger.*", "*tilts the head as a dark mark flashes above the brow.*" }, ziel = { "For a moment, your choice shall be mine.", "%s, for a moment you will go where I lead.", "*slowly draws an unseen string between thumb and forefinger.*", "*tilts the head as a dark mark flashes above the brow.*" }, },
    SHADOW_PROTECTION = { gruppe = { "I know the night. That is why I do not fear it.", "Darkness speaks volumes to those who listen.", "*follows an unseen shadow with a steady gaze*", "*whispers a syllable that fades into the room*" }, ziel = { "I know the night. That is why I do not fear it.", "Hold on, %s. Your story is not finished here.", "*follows an unseen shadow with a steady gaze*", "*whispers a syllable that fades into the room*" }, },
    SHADOW_WORD_DEATH = { gruppe = { "This is the word that cannot be unsaid.", "Darkness speaks volumes to those who listen.", "*follows an unseen shadow with a steady gaze*", "*whispers a syllable that fades into the room*" }, ziel = { "This is the word that cannot be unsaid.", "Your next thought will be more careful, %s.", "*follows an unseen shadow with a steady gaze*", "*whispers a syllable that fades into the room*" }, },
    PRAYER_OF_SHADOW_PROTECTION = { gruppe = { "We walk through darkness, not lost within it.", "Darkness speaks volumes to those who listen.", "*follows an unseen shadow with a steady gaze*", "*whispers a syllable that fades into the room*" }, },
    VAMPIRIC_EMBRACE = { gruppe = { "Strange how close suffering and comfort can be.", "Darkness speaks volumes to those who listen.", "*follows an unseen shadow with a steady gaze*", "*whispers a syllable that fades into the room*" }, ziel = { "Strange how close suffering and comfort can be.", "Your next thought will be more careful, %s.", "*follows an unseen shadow with a steady gaze*", "*whispers a syllable that fades into the room*" }, },
    SILENCE = { gruppe = { "Some answers can only be found in silence.", "No spell can begin without its opening word.", "*touches a finger to the lips as the surrounding air falls quiet.*", "*closes a fist as a shimmering sound dies within it.*" }, ziel = { "Some answers can only be found in silence.", "%s, keep your next incantation to yourself for a moment.", "*touches a finger to the lips as the surrounding air falls quiet.*", "*closes a fist as a shimmering sound dies within it.*" }, },
    SHADOWFORM = { gruppe = { "Nothing in me has gone out. The light falls differently.", "I wear the shadow, but I will not let it wear me.", "*draws the cloak closer as the outline blurs into darkness.*", "*slowly raises the head through a veil of violet mist.*" }, },
    -- Freiwillige, unabhängig vom Zauberbuch nutzbare Priester-RP-Szenen
    BEDSIDE_PRAYER = { gruppe = { "Not every healing begins with magic. Some begin with listening.", "Even the faintest breath deserves our full attention.", "*places a bowl of water beside the bed and checks a patient's pulse.*", "*offers a quiet prayer without lifting the hand from a shoulder.*" }, ziel = { "%s, I shall stay as long as you need me." }, },
    SHRINE_VIGIL = { gruppe = { "The shrine has more questions than answers tonight.", "Perhaps hope is simply the courage to return tomorrow.", "*lights a small candle and shields its flame from the wind.*", "*kneels and remains silent for a moment.*" }, },
    CONFESSION = { gruppe = { "I am listening. No one will be judged hastily here.", "We cannot always change the truth, but we can choose the next step.", "*sits quietly and sets the staff aside.*", "*nods slowly and allows the other person time to speak.*" }, ziel = { "%s, tell me what weighs on your heart." }, },
    LAST_RITES = { gruppe = { "A name remains even when the voice falls silent.", "May the road beyond our sight be peaceful.", "*gently draws a blanket over the fallen.*", "*bows the head and offers a blessing for those left behind.*" }, ziel = { "Your name will not be forgotten, %s." }, },
    MEDITATION = { gruppe = { "Silence is no empty vessel.", "A worthy thought needs space between two breaths.", "*sits upright with both hands resting on the knees.*", "*closes the eyes and counts each breath slowly.*" }, },
    SHADOW_REFLECTION = { gruppe = { "Even a shadow can show where light is missing.", "Those who work with darkness must remember their own voices.", "*lets a dark shimmer dance across the fingers before releasing it.*", "*studies the shadows on a wall without looking away.*" }, },
}